-- 4. 시퀀스 업데이트
-- ============================================

SELECT setval('companies_id_seq', COALESCE((SELECT MAX(id) FROM companies), 1), true);
SELECT setval('company_filter_options_id_seq', COALESCE((SELECT MAX(id) FROM company_filter_options), 1), true);
SELECT setval('boards_id_seq', COALESCE((SELECT MAX(id) FROM boards), 1), true);
SELECT setval('files_id_seq', COALESCE((SELECT MAX(id) FROM files), 1), true);
SELECT setval('board_attachments_id_seq', COALESCE((SELECT MAX(id) FROM board_attachments), 1), true);

-- ============================================
-- 5. 결과 확인
-- ============================================

DO $$
DECLARE
    v_companies INTEGER;
    v_boards INTEGER;
    v_files INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_companies FROM companies;
    SELECT COUNT(*) INTO v_boards FROM boards;
    SELECT COUNT(*) INTO v_files FROM files;

    RAISE NOTICE 'Migration Complete:';
    RAISE NOTICE '  - Companies: %', v_companies;
    RAISE NOTICE '  - Boards: %', v_boards;
    RAISE NOTICE '  - Files: %', v_files;
END $$;
