INSERT INTO temp_damoa_company (seq, uuid, business_name, introduce_title, introduce_description, location_point, tag_skills, tag_specialties, create_datetime, update_datetime, like_count, view_count, location_shortname, homepage_url, primary_thumbnail_url, business_phone, ceo_name, ceo_phone, recommendation_score, like_count_offset, view_count_offset, owner_user_uuid) VALUES (1932, 'afdbc512-d941-4e1e-aa09-0ed871d2c3a0', '상상더하기', '', '안녕하세요. 상상더하기입니다. 이번 포스팅은 리모델링 인테리어 이야기인데요. 경기도 시흥에 위치한 수 이빈이후과!!! 리모델링에서 가장 중요한 요소는 무엇일까? 기존 구조를 바탕으로여 비용은 절감하면서 환경 개선이 주목적이 되겠죠! 기존 구조에 디자인 요소를 더해 새로운 공간을 창출한다는 것이 참 쉬우면서로 어려운데요. 잘 짜인 극본에 조미료를 첨가하는 작업과도 같답니다.어떤 조리료에 따라서 공간 퀄리티는 차이가 나는 것도 이 부분때문일 거예요. 우선 리모델링 공사되기 전 모습을 보도록 할게요. ㅣ디자인 방향, 3D 모델링 원장님께서 리모델링 공사에 대하여 전달해 주신 내용을 토대로 저희만의 디자인 컨셉을 부여하여 탄생된 수 이비인후과의 3D 모델링 결과물인데요. ‘상쾌하다 = 진료를 받고 난 후 상쾌’…', '0101000020E610000000000000000000000000000000000000', '{interior}', '{dermatology,plastic_surgery,orthopedic,internal_medicine,dental,ophthalmology,oriental_medicine,oriental_hospital,obstetrics_gynecology,urology,ent,family_medicine,rehabilitation_medicine,neurosurgery,anesthesiology,psychiatry,surgery,radiology,pediatrics,health_checkup_center}', '2025-10-02 05:39:33.713695+00', '2025-11-08 05:21:12.673136+00', 0, 4, '{seoul}', 'https://sangsang-plus.tistory.com/45', 'images/251014/38fa7a2f-1b96-4878-a39e-fbba312d689c-pre.jpg', '', '김승수', '010-3381-0245', 10, 0, 3, NULL);
