INSERT INTO temp_damoa_board (seq, uuid, title, content, tags, metadata, like_count, view_count, create_datetime, update_datetime, delete_datetime, category_name, writer_uuid, group_id, primary_thumbnail_url, start_datetime, end_datetime) VALUES (494, '0e65d1d3-af9b-4216-9d8c-2040c4022799', '스노우의원 청주', '', '{"스노우의원 청주",와플레이스,100평이하,피부과,피부관리실,복도,모던,그레이,베이지,도장,실사}', '{"link":"http://waplace.kr/bbs/board.php?bo_table=portfolio&page=1#group_22-12","copyright":"waplace","thumbnail_url":"images/251001/052a9102-2d72-4480-a732-d85c96692812-pre.jpg"}', 0, 1, '2025-09-30 18:44:44.547542+00', '2025-10-16 01:56:18.946743+00', NULL, 'photo', '97957035-5cba-47eb-987b-593bf1bcf45f', NULL, '', NULL, NULL);
INSERT INTO temp_damoa_board (seq, uuid, title, content, tags, metadata, like_count, view_count, create_datetime, update_datetime, delete_datetime, category_name, writer_uuid, group_id, primary_thumbnail_url, start_datetime, end_datetime) VALUES (485, '6ab86358-6439-405a-a692-b38e5e0868ff', '뮤즈클리닉 하남', '', '{"뮤즈클리닉 하남",와플레이스,200평이상,피부과,대기실,상담실,모던,도장,금속,콩자갈,실사}', '{"link":"http://waplace.kr/bbs/board.php?bo_table=portfolio&page=1#group_21-30","copyright":"waplace","thumbnail_url":"images/251001/9475a833-b601-4caf-904c-8ede9ddde799-pre.jpg"}', 0, 1, '2025-09-30 18:41:39.988019+00', '2025-10-13 07:22:22.881+00', NULL, 'photo', '97957035-5cba-47eb-987b-593bf1bcf45f', NULL, '', NULL, NULL);
