INSERT INTO temp_damoa_board (seq, uuid, title, content, tags, metadata, like_count, view_count, create_datetime, update_datetime, delete_datetime, category_name, writer_uuid, group_id, primary_thumbnail_url, start_datetime, end_datetime) VALUES (667, '4db7116e-5393-4c01-a411-05e3ce0221c2', '신규 서비스 오픈 안내', '<p style="text-align: left;"><img src="https://d3jwbzkv7b53n2.cloudfront.net/images/pdf_thumbnails/1761119071692_제목 없는 디자인.pdf.jpg" alt="제목 없는 디자인.pdf"></p><h2 style="text-align: left;"><span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>신규 서비스 오픈 안내</strong></span><span>﻿</span></h2><p style="text-align: left;">드디어 <span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>병원인테리어다모아</strong></span><span>﻿</span>의 <span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>신규 서비스</strong></span><span>﻿</span>가 오픈되었습니다!<br>이번 신규 서비스는 사용자 편의성과 전문성을 한층 더 높여, 고객님께 완전히 새로운 인테리어 경험을 제공하기 위해 준비했습니다.</p><p style="text-align: left;"><strong>주요 서비스</strong></p><ul><li><p style="text-align: left;"><span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>공개 디자인 공모전</strong></span><span>﻿</span> 및 <span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>플래너 견적제안</strong></span><span>﻿</span> 기능 도입</p></li><li><p style="text-align: left;"><span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>무료 도면 제공</strong></span><span>﻿</span>, 쉽고 빠른 상담 서비스</p></li><li><p style="text-align: left;"><span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>전문 시공업체</strong></span><span>﻿</span> 매칭 자동화, 업체 리뷰 시스템 추가</p></li></ul><p style="text-align: left;"><strong>오픈 이벤트</strong></p><ul><li><p style="text-align: left;">신규 회원 전원에게 인테리어 상담 무료<span>﻿</span></p></li><li><p style="text-align: left;">설계툴에서 배치 완료한 도면 무료그리기</p></li><li><p style="text-align: left;">공개입찰 무료</p></li></ul><p style="text-align: left;"><strong>이용 방법</strong><br>회원가입 후 맞춤 플래너를 선택하거나, 공개 디자인 공모전 신청, 무료상담을 바로 이용해보세요. 궁금한 점은 실시간 고객센터에서 언제든 문의 가능합니다.</p><p style="text-align: left;">지금 바로 <span style="font-size: 1rem; color: oklch(0.3039 0.04 213.68);"><strong>병원인테리어다모아</strong></span><span>﻿</span>에서 새롭게 바뀐 서비스를 만나보시고, 더 쉽고 빠르게 인테리어 프로젝트를 시작하세요!</p>', '{"신규 서비스",오픈,무료도면,디자인공모,플래너,매칭,인테리어,병원}', '{}', 0, 918, '2025-10-22 07:44:36.040804+00', '2025-11-28 02:01:25.060065+00', NULL, 'notice', '97957035-5cba-47eb-987b-593bf1bcf45f', 'announcement', 'images/pdf_thumbnails/1761118984356_제목 없는 디자인.pdf.jpg', NULL, NULL);
INSERT INTO temp_damoa_board (seq, uuid, title, content, tags, metadata, like_count, view_count, create_datetime, update_datetime, delete_datetime, category_name, writer_uuid, group_id, primary_thumbnail_url, start_datetime, end_datetime) VALUES (532, '517b8c89-95e6-4783-beb8-92814542a033', '개원절차 9단계가이드', '<h1 style="text-align: left;">병의원 개원절차 가이드</h1><p style="text-align: left;">성공적인 개원을 위한 9단계 체크리스트</p><p style="text-align: left;">1</p><p style="text-align: left;">입지 및 건물용도 확인</p><ul><li><p style="text-align: left;">의원: 근린생활시설(1종) 필요</p></li><li><p style="text-align: left;">병원: 의료시설 용도 필요</p></li><li><p style="text-align: left;">용도 불일치 시 개원 불가능</p></li></ul><p style="text-align: left;">2</p><p style="text-align: left;">인테리어 계약</p><ul><li><p style="text-align: left;">병원 전문업체와 계약 권장</p></li><li><p style="text-align: left;">의료법, 소방법 기준 준수</p></li><li><p style="text-align: left;">효율적인 동선 설계 중요</p></li></ul><p style="text-align: left;">3</p><p style="text-align: left;">보건소 신고/허가</p><ul><li><p style="text-align: left;">인테리어 80-90% 완료 시 신고</p></li><li><p style="text-align: left;">의원: 신고 (4만원) / 병원: 허가 (10만원)</p></li><li><p style="text-align: left;">처리기간: 약 10일</p></li></ul><p style="text-align: left;">4</p><p style="text-align: left;">사업자 등록</p><ul><li><p style="text-align: left;">개설신고 완료 후 진행</p></li><li><p style="text-align: left;">세무서 또는 홈택스 신청</p></li><li><p style="text-align: left;">사업자등록증 발급 확인</p></li></ul><p style="text-align: left;">5</p><p style="text-align: left;">현장 조사</p><ul><li><p style="text-align: left;">신고 후 약 1주일 뒤 실시</p></li><li><p style="text-align: left;">소방서, 보건소 합동 점검</p></li><li><p style="text-align: left;">소독기, 환기시설, 소방시설 점검</p></li></ul><p style="text-align: left;">6</p><p style="text-align: left;">개설 필증 발급</p><ul><li><p style="text-align: left;">현장조사 통과 후 발급</p></li><li><p style="text-align: left;">요양기관기호 신청</p></li><li><p style="text-align: left;">보험청구를 위한 필수 과정</p></li></ul><p style="text-align: left;">7</p><p style="text-align: left;">행정처리</p><ul><li><p style="text-align: left;">건강보험공단 인증서 발급</p></li><li><p style="text-align: left;">EMR 프로그램 등록</p></li><li><p style="text-align: left;">세무 관련 서류 제출</p></li></ul><p style="text-align: left;">8</p><p style="text-align: left;">개원 준비</p><ul><li><p style="text-align: left;">직원 교육 및 리허설</p></li><li><p style="text-align: left;">의료장비, 시설 최종 점검</p></li><li><p style="text-align: left;">카드단말기 설치 완료</p></li></ul><p style="text-align: left;">9</p><p style="text-align: left;">정식 개원</p><ul><li><p style="text-align: left;">모든 준비사항 완료 확인</p></li><li><p style="text-align: left;">간판 설치 및 홍보</p></li><li><p style="text-align: left;">환자 진료 시작</p></li></ul><h3 style="text-align: left;">성공적인 개원을 위한 팁</h3><p style="text-align: left;">체계적인 준비와 전문가의 도움이 안정적인 개원의 핵심입니다.<br>각 단계별 충분한 준비기간을 확보하여 차질 없이 진행하세요.</p>', '{}', '{}', 0, 58, '2025-10-01 23:59:56.439152+00', '2025-11-28 05:34:40.802719+00', NULL, 'resource', '97957035-5cba-47eb-987b-593bf1bcf45f', 'opening_checklist', 'images/251002/0bbcf4cd-a340-4dc0-b7e3-231c4933aa1b-pre.jpg', NULL, NULL);
INSERT INTO temp_damoa_board (seq, uuid, title, content, tags, metadata, like_count, view_count, create_datetime, update_datetime, delete_datetime, category_name, writer_uuid, group_id, primary_thumbnail_url, start_datetime, end_datetime) VALUES (540, 'a0e70092-7899-4cb1-9094-124626346a33', '의원 장애인 편의시설 및 안전 규정', '<p style="text-align: left;">🏥♿</p><h1 style="text-align: left;">의원 장애인 편의시설 및 안전 규정</h1><p style="text-align: left;">병원·의원 개설 시 장애인 편의시설 설치와 안전 규정 준수는 필수입니다.</p><p style="text-align: left;">이는 환자의 접근성과 안전을 보장하고, 개원 인허가에도 직접적으로 영향을 미칩니다.</p><p style="text-align: left;">📋 1. 관련 법규</p><p style="text-align: left;"><strong>장애인·노인·임산부 등의 편의증진 보장에 관한 법률</strong></p><p style="text-align: left;"><strong>장애인차별금지법</strong></p><p style="text-align: left;"><strong>의료법</strong></p><p style="text-align: left;"><strong>건축법 및 소방법</strong></p><p style="text-align: left;">🏢 2. 필수 편의시설 항목</p><p style="text-align: left;">의원 규모(바닥면적, 층수)에 따라 요구 기준이 달라질 수 있으나, 일반적으로 다음과 같은 시설이 요구됩니다.</p><p style="text-align: left;">(1) 출입구</p><ul><li><p style="text-align: left;">경사로 설치 (기울기 1:12 이하 권장)</p></li><li><p style="text-align: left;">자동문 또는 문폭 최소 0.8m 이상 확보</p></li><li><p style="text-align: left;">문턱 제거 또는 2cm 이하</p></li></ul><p style="text-align: left;">(2) 내부 이동 공간</p><ul><li><p style="text-align: left;">복도 폭 1.2m 이상 (휠체어 회전 가능)</p></li><li><p style="text-align: left;">진료실·치료실 출입문 0.8m 이상</p></li></ul><p style="text-align: left;">(3) 화장실</p><ul><li><p style="text-align: left;">장애인 전용 화장실(남녀 구분 가능, 소규모 의원은 공용도 가능)</p></li><li><p style="text-align: left;">내부 회전 반경 1.5m 이상</p></li><li><p style="text-align: left;">손잡이·비상벨 설치</p></li></ul><p style="text-align: left;">(4) 기타</p><ul><li><p style="text-align: left;">점자 표지판 (출입구·화장실·층별 안내)</p></li><li><p style="text-align: left;">안내 데스크 저상형 부분 설치</p></li><li><p style="text-align: left;">대기실 좌석 일부 휠체어 공간 비워두기</p></li></ul><p style="text-align: left;">🛡️ 3. 안전 규정</p><h4 style="text-align: left;">🔥소방안전</h4><ul><li><p style="text-align: left;">비상구 확보 (폭 0.9m 이상)</p></li><li><p style="text-align: left;">소화기 및 화재감지기 의무 설치</p></li><li><p style="text-align: left;">피난유도등, 비상조명 설치</p></li></ul><h4 style="text-align: left;">⚡전기·가스</h4><ul><li><p style="text-align: left;">누전 차단기 설치</p></li><li><p style="text-align: left;">산소통·의료가스 사용 시 전용 보관실 확보</p></li></ul><h4 style="text-align: left;">🏥환자 안전</h4><ul><li><p style="text-align: left;">미끄럼 방지 바닥재 사용</p></li><li><p style="text-align: left;">모서리 라운딩 처리</p></li><li><p style="text-align: left;">응급환자용 들것 이동 가능한 동선 확보</p></li></ul><p style="text-align: left;">⚖️ 4. 설치 예외 및 완화 기준</p><p style="text-align: left;">기존 건물 리모델링 시, 구조적으로 설치가 불가능한 경우 지자체 심의 후 일부 면제 가능</p><h4 style="text-align: left;">⚠️ 주의사항</h4><p style="text-align: left;">그러나 화장실, 출입구, 기본 안전시설은 필수로 보는 경우가 많음</p><p style="text-align: left;">✅ 5. 개원 전 체크리스트</p><p style="text-align: left;">출입구 경사로 및 자동문 설치 여부 확인</p><p style="text-align: left;">복도·진료실 문폭 기준 충족 여부 확인</p><p style="text-align: left;">장애인 화장실 설치 여부 및 내부 규격 충족 여부 확인</p><p style="text-align: left;">소방안전 기준(소화기·비상구·비상등) 충족 여부 확인</p><p style="text-align: left;">비상벨·점자안내판·손잡이 설치 여부 확인</p><p style="text-align: left;"><strong>참조 이미지</strong></p><p style="text-align: left;">🖼 휠체어 경사로 시공 예시</p><p style="text-align: left;">🖼 장애인 화장실 평면도 예시</p><p style="text-align: left;">🖼 의원 내부 복도 폭 및 안전 손잡이 설치 사례</p>', '{}', '{}', 0, 96, '2025-10-03 02:27:57.45847+00', '2025-11-26 20:49:36.184504+00', NULL, 'resource', '97957035-5cba-47eb-987b-593bf1bcf45f', 'regulation_administration', 'images/251003/64fdb58f-34ba-42b2-aa04-2a255404c95a-pre.jpg', NULL, NULL);
